svg.script:
const avoidRoot = document.getElementById("avoid-root");
const leftArm = document.getElementById("left-arm");
const rightArm = document.getElementById("right-arm");
const shadow = document.getElementById("shadow-js");

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, Number.isFinite(n) ? n : 0));
}

function setPose(direction) {
  if (direction === "left") {
    leftArm.innerHTML = '<rect x="0" y="8" width="2" height="2"/><rect x="-3" y="8" width="3" height="2"/><rect x="-4" y="6" width="2" height="2"/>';
    rightArm.innerHTML = '<rect x="13" y="8" width="2" height="2"/><rect x="12" y="6" width="2" height="2"/>';
    return;
  }
  if (direction === "right") {
    leftArm.innerHTML = '<rect x="1" y="8" width="2" height="2"/><rect x="1" y="6" width="2" height="2"/>';
    rightArm.innerHTML = '<rect x="13" y="8" width="2" height="2"/><rect x="15" y="8" width="3" height="2"/><rect x="17" y="6" width="2" height="2"/>';
    return;
  }
  leftArm.innerHTML = '<rect x="0" y="8" width="2" height="2"/><rect x="-1" y="6" width="2" height="2"/>';
  rightArm.innerHTML = '<rect x="13" y="8" width="2" height="2"/><rect x="14" y="6" width="2" height="2"/>';
}

function setAvoidance(direction, x, y) {
  let shiftX = 0;
  let shiftY = 1;
  if (direction === "left") {
    shiftX = 8;
    shiftY = 2;
  } else if (direction === "right") {
    shiftX = -8;
    shiftY = 2;
  } else {
    shiftX = x <= 0 ? 7 : -7;
    shiftY = y <= 0 ? 3 : -1;
  }
  avoidRoot.setAttribute("transform", "translate(" + shiftX + " " + shiftY + ")");
}

function setFileDragCatch(payload) {
  const p = payload || {};
  const x = clamp(Number(p.x), -1, 1);
  const y = clamp(Number(p.y), -1, 1);
  const direction = p.direction === "left" || p.direction === "right" || p.direction === "center"
    ? p.direction
    : (x < -0.25 ? "left" : (x > 0.25 ? "right" : "center"));

  setPose(direction);
  setAvoidance(direction, x, y);
  shadow.setAttribute("transform", "translate(" + (x * 0.8).toFixed(2) + " 0)");
}

window.__clawdSetFileDragCatch = setFileDragCatch;
setFileDragCatch({ x: 0, direction: "center" });
